class Solution{fun getMaxGridHappiness(m:Int,n:Int,introvertsCount:Int,extrovertsCount:Int):Int{val I=introvertsCount;val E=extrovertsCount;var rows=m;var cols=n;if(cols>rows){val t=rows;rows=cols;cols=t};var k=1;repeat(cols){k*=3};val h=IntArray(k);val a=IntArray(k);val b=IntArray(k);for(x in 0 until k){var q=x;var p=0;repeat(cols){val d=q%3;q/=3;if(d==1){h[x]+=120;a[x]++}else if(d==2){h[x]+=40;b[x]++};if(d>0&&p>0)h[x]+=(if(d==1)-30 else 20)+(if(p==1)-30 else 20);p=d}};val M=HashMap<String,Int>();fun f(r:Int,i:Int,e:Int,p:Int):Int{if(r==rows)return 0;val z="$r,$i,$e,$p";M[z]?.let{return it};var v=0;for(c in 0 until k)if(a[c]<=i&&b[c]<=e){var x=p;var y=c;var s=0;repeat(cols){val u=x%3;val d=y%3;x/=3;y/=3;if(u>0&&d>0)s+=(if(u==1)-30 else 20)+(if(d==1)-30 else 20)};v=maxOf(v,h[c]+s+f(r+1,i-a[c],e-b[c],c))};M[z]=v;return v};return f(0,I,E,0)}}
